data.transform:
(
  $C := $state.context;
  $R := $C.REQUEST.DATA;
  $L := $C.LOCAL;
  $lines := $L.purchaseOrder.lines;
  $r := $L.purchaseOrder.receipts.edges.node; 
  $id := $cuid();
  $m := (
    $s :=  $sift($R.lines,function($v, $k) {$v.newMaster});
    $each($s, function($v, $k) {(
      $mid := $cuid();
      {
        "lineid": $k,
        "id": $mid
      }
      )
    })
  );
  $p := { 
    "CR": $isNilOrEmpty($r.id)  ? {
          "create": {
            "id": $id,
            "locationId": $R.locationId,
            "purchaseOrderId": $R.id,
            "statusId": $C.DEFAULT.receiptStatusId,
            "shipper": $R.shipmentNumber

          }
        }  : [],

    "PO": [{
      "update": {
        "shipmentNumber": $R.shipmentNumber,
        "purchaseOrderStatusId": "Partially Received"
      },"where": {
        "id": $R.id
      }
    }],

    "CM": [$m.{
      "create": {
        "id":id,
        "masterInventoryStatusId": "Receiving",
        "locationId": $R.locationId
      }
    }],

    "L":$lines.(
      $rlid := $cuid();
      $line := $;
      $unit := pendingQuantity.unitId;
      $l := $lookup($R.lines, $line.id);
      $qty := $L.lineQty[id=$line.id];
      {
        "CRL": $isNilOrEmpty(receiptLines.edges.node.id) ? {
          "create": {
            "id": $rlid,
            "receiptId": $coalesce([$r.id,$id]),
            "licensePlates": $l.containers,
            "lotNumber": $l.lot,
            "quantityPerLicensePlate": {
              "value":  $l.qtyPer,
              "unitId": $unit
            },
            "quantity": {
              "value": $l.qtyPer * $l.containers,
              "unitId": $unit
            },
            "purchaseOrderLineId": $line.id,
            "statusId": $C.DEFAULT.receiptStatusId
          }
        } : [],

        "URL": [receiptLines.edges[0].node.{
          "update": {
            "quantity":  quantity.{
              "value": $l.qtyPer * $l.containers + value,
              "unitId": unitId
            }
          },
          "where": {
            "id":id
          }
        }],

        "POL": {
          "update": {
            "balanceQuantity": {
              "value": $qty.balance,
              "unitId":$unit
            },
            "pendingQuantity": {
              "value":$qty.pending,
              "unitId": $unit
            },
            "purchaseOrderLineStatusId": $qty.balance <= 0 ? "Pending Confirmation" : "Partially Received"
          }, 
          "where": {
            "id":id
          }
        },

        "I": $line.product.productTypeId != "OthCharge" ? [1..$l.containers].{
          "create": {
            "active":false,
            "productStrategyProcessId":$line.productStrategyProcess.id,
            "productId":$line.product.id,
            "locationId": $R.locationId,
            "quantity": { 
              "value": $l.qtyPer,
              "unitId":$unit
            },
            "receiptLineId":$isNilOrEmpty($line.receiptLines.edges.node.id) ? $rlid :$line.receiptLines.edges[0].node.id ,
            "inventoryStatusId":  $C.DEFAULT.inventoryStatusId,
            "inventoryTypeId": "Raw Material",
            "barcode":"",
            "grossWeight":0,
            "supplierId":$L.purchaseOrder.supplierId,
            "netWeight":0,
            "tareWeight":0,
            "masterInventoryId": $l.newMaster ? $m[lineid=$line.id].id : $l.master.id
          }
        } : []
      }
    )
  };

  {
    "payloadPO": [$p.PO],
    "payloadCR": [$p.CR],
    "payloadCRL": [$p.L.CRL],
    "payloadURL": [$p.L.URL],
    "payloadPOL": [$p.L.POL],
    "payloadI": [$p.L.I],
    "payloadCM": [$p.CM]
  }

)

